import sys,json; sys.path.insert(0,'/tmp/dbtest')
src=open('/tmp/dbtest/e2e_full.py').read().split("# ---------- seed")[0]
exec(src)
PROD=q1("select id from public.products where slug='epoxy-floor-kit'"); ZONE=q1("select id from public.delivery_zones limit 1")
def new_order(key,qty=1,method='mpesa'):
    items=json.dumps([{"product_id":PROD,"quantity":qty}])
    ok,r=call('anon',f"select public.create_secure_customer_order('Test Customer','t{key}@example.co.ke','0711000{key}','{items}'::jsonb,'',NULL,'{ZONE}','Westlands, Nairobi','{method}','ord-{key}')")
    return r['order_id'] if ok and isinstance(r,dict) and r.get('success') else None
def attempt(order,key,method='mpesa',amount=2000):
    ok,a=call('service_role',f"select public.create_payment_attempt_atomic_360('order','{order}','{method}','{method}','{method}',{amount},'KES','254711000111','{key}','{key[0]*64}',NULL)")
    return a
print('=== A2. Input validation (fixing my earlier test mistakes)')
items=json.dumps([{"product_id":PROD,"quantity":999}])
ok,e=call('anon',f"select public.create_secure_customer_order('Test Customer','x@x.co','0712345678','{items}'::jsonb,'',NULL,NULL,NULL,'mpesa','k-big')")
check('ordering more than is in stock is refused', (not ok) or (isinstance(e,dict) and not e.get('success')), e); print('  ->',str(e)[:120])
O=q1("select id from public.orders order by created_at limit 1")
ok,e=call('authenticated',f"select public.update_order_delivery_address('{O}','abc')",sub=OWNER); check('address shorter than 5 characters refused', not ok, e)
print('=== E. Stale payment expiry (new scheduled job)')
o2=new_order('201'); a2=attempt(o2,'e2-key'); tx2=a2['payment_transaction_id']; at2=a2['attempt_id']
o3=new_order('202',method='bank_transfer'); a3=attempt(o3,'e3-key','bank_transfer')
o4=new_order('203'); a4=attempt(o4,'e4-key'); at4=a4['attempt_id']
run(f"update public.payment_attempts set created_at=now()-interval '3 hours' where id in ('{at2}','{a3['attempt_id']}'); update public.payment_transactions set checkout_expires_at=now()-interval '2 hours', created_at=now()-interval '3 hours' where id in ('{tx2}','{a3['payment_transaction_id']}')")
ok,r=call('service_role',"select public.expire_stale_payment_attempts_360(30)"); check('expiry job runs as service role', ok and r.get('success'), r); print('  ->',r)
check('old M-Pesa attempt expired', q1(f"select status from public.payment_attempts where id='{at2}'")=='expired', q1(f"select status from public.payment_attempts where id='{at2}'"))
check('its transaction marked failed (customer can retry)', q1(f"select status from public.payment_transactions where id='{tx2}'")=='failed')
check('bank-transfer attempt NOT expired (staff confirm manually)', q1(f"select status from public.payment_attempts where id='{a3['attempt_id']}'")!='expired', q1(f"select status from public.payment_attempts where id='{a3['attempt_id']}'"))
check('fresh M-Pesa attempt left alone', q1(f"select status from public.payment_attempts where id='{at4}'")!='expired')
ok,e=call('anon',"select public.expire_stale_payment_attempts_360(30)"); check('anonymous users cannot run the expiry job', not ok, e)
ok,e=call('authenticated',"select public.expire_stale_payment_attempts_360(30)",sub=OWNER); check('browser staff cannot run the expiry job directly', not ok, e)
ok,a5=call('service_role',f"select public.create_payment_attempt_atomic_360('order','{o2}','mpesa','mpesa','mpesa',2000,'KES','254711000111','e2-retry','{'z'*64}',NULL)")
check('customer can start a NEW payment after expiry', ok and a5.get('success'), a5)
print('=== F. Late payment after expiry still reconciles')
run(f"update public.payment_transactions set provider_transaction_id='CKO-LATE' where id='{tx2}'")
ok,r=call('service_role',f"select public.apply_customer_payment_provider_event('mpesa','evt-late','stk_callback','successful',2000,'KES','{o2}',NULL,'CKO-LATE','REF-LATE','{{}}'::jsonb)")
check('late success callback accepted', ok and r.get('success'), r)
check('order paid despite the earlier expiry', q1(f"select payment_status from public.orders where id='{o2}'")=='paid', q1(f"select payment_status from public.orders where id='{o2}'"))
print('=== G. Callback arrives BEFORE the checkout id is saved')
o6=new_order('206'); a6=attempt(o6,'g6-key'); tx6=a6['payment_transaction_id']
ok,r=call('service_role',f"select public.apply_customer_payment_provider_event('mpesa','evt-race','stk_callback','successful',2000,'KES','{o6}',NULL,'CKO-RACE','REF-R','{{}}'::jsonb)")
check('early callback is recorded as failed (not lost)', ok and r.get('success') is False and 'not found' in str(r.get('error','')).lower(), r)
run(f"update public.payment_transactions set provider_transaction_id='CKO-RACE' where id='{tx6}'")
ok,r=call('service_role',f"select public.apply_customer_payment_provider_event('mpesa','evt-race','stk_callback','successful',2000,'KES','{o6}',NULL,'CKO-RACE','REF-R','{{}}'::jsonb)")
check('retry of the SAME event id succeeds once the checkout id is saved', ok and r.get('success'), r)
check('order paid after the retry', q1(f"select payment_status from public.orders where id='{o6}'")=='paid')
print('=== H. Public site settings visibility (RLS)')
run("insert into public.site_settings(setting_key,setting_value) values ('contact','{\"email\":\"hello@topline.test\"}'::jsonb),('company','{\"tax_id\":\"A123456789Z\"}'::jsonb),('internal_secret','{\"k\":1}'::jsonb) on conflict (setting_key) do update set setting_value=excluded.setting_value")
ok,v=call('anon',"select string_agg(setting_key,',' order by setting_key) from public.site_settings")
check('visitors can read contact details', ok and 'contact' in str(v), v)
check('visitors cannot read company (tax IDs)', 'company' not in str(v), v)
check('visitors cannot read unlisted keys', 'internal_secret' not in str(v), v); print('  anon sees:',v)
ok,e=call('anon',"insert into public.site_settings(setting_key,setting_value) values ('contact','{}'::jsonb) on conflict (setting_key) do update set setting_value=excluded.setting_value"); check('visitors cannot write settings', not ok, e)
ok,v=call('authenticated',"select string_agg(setting_key,',' order by setting_key) from public.site_settings",sub=OWNER); check('staff with content access still see every key', ok and 'company' in str(v) and 'internal_secret' in str(v), v)
print('=== I. Scheduler')
ok,r=call('service_role',"select public.start_automation_job('expire_payment_attempts',60,'test')"); check('scheduler accepts the new job', ok and r.get('acquired'), r)
ok,e=call('service_role',"select public.start_automation_job('drop_everything',60,'test')"); check('unknown job names rejected', not ok, e)
ok,e=call('authenticated',"select public.start_automation_job('expire_payment_attempts',60,'test')",sub=OWNER); check('browser users cannot start jobs', not ok, e)
cj=q1("select string_agg(jobname||'='||schedule,'; ') from cron.job where jobname ilike '%payment%'"); print('  cron entries:',cj)
check('a cron entry exists for the new job', bool(cj) and 'expire' in cj, cj)
